def calc(expr: str) -> int | str:
    s = expr
    n = len(s)
    i = 0

    class _Err(Exception):
        pass

    def skip() -> None:
        nonlocal i
        while i < n and s[i] == " ":
            i += 1

    def trunc_div(a: int, b: int) -> int:
        if b == 0:
            raise _Err
        q = abs(a) // abs(b)
        if (a < 0) != (b < 0):
            q = -q
        return q

    def parse_primary() -> int:
        nonlocal i
        skip()
        if s[i] == "(":
            i += 1
            v = parse_expr()
            skip()
            i += 1
            return v
        start = i
        while i < n and s[i].isdigit():
            i += 1
        return int(s[start:i])

    def parse_unary() -> int:
        nonlocal i
        nodes: list[tuple[int, int]] = []
        while True:
            sign = 1
            skip()
            while i < n and s[i] == "-":
                sign = -sign
                i += 1
                skip()
            nodes.append((sign, parse_primary()))
            skip()
            if i < n and s[i] == "^":
                i += 1
                continue
            break
        sign, val = nodes[-1]
        val = sign * val
        for sign, base in reversed(nodes[:-1]):
            if val < 0:
                raise _Err
            val = sign * pow(base, val)
        return val

    def parse_term() -> int:
        nonlocal i
        v = parse_unary()
        while True:
            skip()
            if i >= n or s[i] not in "*/%":
                break
            op = s[i]
            i += 1
            rhs = parse_unary()
            if op == "*":
                v *= rhs
            else:
                q = trunc_div(v, rhs)
                v = q if op == "/" else v - rhs * q
        return v

    def parse_expr() -> int:
        nonlocal i
        v = parse_term()
        while True:
            skip()
            if i >= n or s[i] not in "+-":
                break
            op = s[i]
            i += 1
            rhs = parse_term()
            v = v + rhs if op == "+" else v - rhs
        return v

    try:
        return parse_expr()
    except _Err:
        return "error"
